# Energy Research Warehouse (ERW): the R package against the conformance file (session 1006).
# Written by packages/conformance/write_runners.py from conformance.json; needs the erw package and
# ERW_LIVE_URL and ERW_LIVE_KEY in the environment. Prints one line a call and the count that pass.
library(erw)
pass <- 0L
stamp <- function(t) format(t, "%Y-%m-%dT%H:%M:%SZ", tz = "UTC")
report <- function(ok, label) {
  cat(if (isTRUE(ok)) "ok   " else "FAIL ", label, "\n", sep = "")
  pass <<- pass + isTRUE(ok)
}
d <- erw_fetch("eia_fuel_spot_prices", entity = c("eia:henry_hub"), start = "2025-01-01", end = "2026-01-01", backend = "live")
t <- if ("event_date" %in% names(d)) d$event_date else if ("ts_utc" %in% names(d)) d$ts_utc else as.POSIXct(d$status_date, tz = "UTC")
report(nrow(d) == 247 && stamp(min(t)) == "2025-01-02T00:00:00Z" && stamp(max(t)) == "2025-12-31T00:00:00Z", "01 fetch eia_fuel_spot_prices")
