m <- tryCatch({erw_fetch("iso_rtm_hub_prices", start = "2026-10-20", backend = "live"); ""}, error = function(e) conditionMessage(e))
report(m == "iso_rtm_hub_prices is not public: unsettled. MISO's terms ask for written permission, which the ERW has not recorded (license needed since 2026-10-21). The ERW's license record: https://github.com/SamuelEnrique/erw/blob/main/docs/licenses.md", "18 refusal iso_rtm_hub_prices")
s <- erw_standard("eia860m_retired_generators", backend = "live")
report(s$shape == "entities" && identical(s$key, c("entity_id")), "19 standard eia860m_retired_generators")
t <- erw_tables()
r <- t[t$table == "eia_fuel_spot_prices", ]
report(nrow(r) == 1 && r$shape == "series" && r$verdict == "public" && r$in_live == "yes" && nrow(t) >= 299, "20 tables eia_fuel_spot_prices")
cat(pass, "of 20 pass\n")
